#' Two-Component First Event (Python)
#'
#' 
#' @param data .
#' @param statusA .
#' @param eventA .
#' @param freeA .
#' @param timeA .
#' @param statusB .
#' @param eventB .
#' @param freeB .
#' @param timeB .
#' @param preview_rows .
#' @param showPreview .
#' @param showPlot .
#' @param showReport .
#' @param use_admin .
#' @param admin_cutoff .
#' @param subject .
#' @param require_unique_id .
#' @param audit_subject .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mapping} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$counts} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$preview} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$report} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$distribution} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$timeOut} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$statusOut} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$sourceOut} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$adminAudit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$identityAudit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$repeatedSubjects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$identityPolicy} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pyfirstevent <- function(
    data,
    statusA = NULL,
    eventA,
    freeA,
    timeA = NULL,
    statusB = NULL,
    eventB,
    freeB,
    timeB = NULL,
    preview_rows = 20,
    showPreview = TRUE,
    showPlot = FALSE,
    showReport = FALSE,
    use_admin = FALSE,
    admin_cutoff = "",
    subject = NULL,
    require_unique_id = FALSE,
    audit_subject = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyfirstevent requires jmvcore to be installed (restart may be required)")

    if ( ! missing(statusA)) statusA <- jmvcore::resolveQuo(jmvcore::enquo(statusA))
    if ( ! missing(timeA)) timeA <- jmvcore::resolveQuo(jmvcore::enquo(timeA))
    if ( ! missing(statusB)) statusB <- jmvcore::resolveQuo(jmvcore::enquo(statusB))
    if ( ! missing(timeB)) timeB <- jmvcore::resolveQuo(jmvcore::enquo(timeB))
    if ( ! missing(subject)) subject <- jmvcore::resolveQuo(jmvcore::enquo(subject))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(statusA), statusA, NULL),
            `if`( ! missing(timeA), timeA, NULL),
            `if`( ! missing(statusB), statusB, NULL),
            `if`( ! missing(timeB), timeB, NULL),
            `if`( ! missing(subject), subject, NULL))

    for (v in statusA) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in statusB) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pyfirsteventOptions$new(
        statusA = statusA,
        eventA = eventA,
        freeA = freeA,
        timeA = timeA,
        statusB = statusB,
        eventB = eventB,
        freeB = freeB,
        timeB = timeB,
        preview_rows = preview_rows,
        showPreview = showPreview,
        showPlot = showPlot,
        showReport = showReport,
        use_admin = use_admin,
        admin_cutoff = admin_cutoff,
        subject = subject,
        require_unique_id = require_unique_id,
        audit_subject = audit_subject,
        showConsole = showConsole)

    analysis <- pyfirsteventClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

